import math

# Target ratio: 7/335
# Condition: 335 * (a1-1)(a2-1)(a3-1) = 7 * a1 * a2 * a3

A_MAX = 100

found_solutions = []

# Search for m=3
for a1 in range(2, A_MAX):
    for a2 in range(a1 + 1, A_MAX):
        for a3 in range(a2 + 1, A_MAX + 1):

            LHS = 335 * (a1 - 1) * (a2 - 1) * (a3 - 1)
            RHS = 7 * a1 * a2 * a3

            if LHS == RHS:
                found_solutions.append((a1, a2, a3))

if found_solutions:
    print(f"Found {len(found_solutions)} solutions for m=3:")
    for sol in found_solutions:
        print(f"Solution: {sol}")
else:
    print("No solutions found for m=3 with a_i <= 100.")

